def is_rainbow(arr: list[int]) -> str:
    if set(arr) != set(range(1, 8)):
        return 'no'
    if arr != arr[::-1]:
        return 'no'
    curr = 1
    for x in arr[:(len(arr) + 1) // 2]:
        if x == curr:
            continue
        elif x == curr + 1:
            curr += 1
        else:
            return 'no'
    return 'yes' if curr == 7 else 'no'
